<script setup lang="ts">
import {computed,ref} from 'vue';import type {EChartsCoreOption} from 'echarts/core';import ChartCanvas from '../../Operation/components/ChartCanvas.vue';import type {FloodHistoryPoint} from '../../../types/flood';
const props=defineProps<{points:FloodHistoryPoint[]}>();const metric=ref<'waterLevel'|'rainfall'|'pumpCapacity'|'riskScore'>('waterLevel');
const metrics={waterLevel:{name:'水位',unit:'cm',color:'#57c9eb'},rainfall:{name:'降雨',unit:'mm/h',color:'#80aef1'},pumpCapacity:{name:'有效泵排水能力',unit:'m³/s',color:'#58c6a8'},riskScore:{name:'场景风险',unit:'分',color:'#e7ad61'}};
const option=computed<EChartsCoreOption>(()=>({animation:false,backgroundColor:'transparent',tooltip:{trigger:'axis'},grid:{left:65,right:35,top:32,bottom:40},xAxis:{type:'value',name:'仿真分钟',axisLabel:{color:'#86a4b6'},splitLine:{show:false}},yAxis:{type:'value',name:metrics[metric.value].unit,axisLabel:{color:'#86a4b6'},splitLine:{lineStyle:{color:'#1b3647'}}},series:[{type:'line',showSymbol:false,lineStyle:{width:2,color:metrics[metric.value].color},areaStyle:{color:metrics[metric.value].color,opacity:.1},data:props.points.map(p=>[p.time/60,p[metric.value]])}]}));
</script><template><section class="panel flood-trends" data-testid="flood-trends" :data-count="points.length"><header><h3>事故演化曲线 <small>最近 60 仿真分钟 · 最多 1800 点</small></h3><div role="tablist" aria-label="内涝趋势指标"><button v-for="(m,key) in metrics" :key="key" role="tab" :aria-selected="metric===key" @click="metric=key">{{m.name}}</button></div></header><ChartCanvas :option="option" :label="metrics[metric].name+'仿真趋势'"/><p v-if="!points.length">启动场景后记录本次演化，不填充虚构历史。</p></section></template>
